"""Conveyor skill catalogue. Initial deal/keep counts are independent of effects."""
SKILLS = {}

def skill(key, name, group, deal, keep, text):
    SKILLS[key] = dict(id=key, name=name, group=group, deal=deal, keep=keep, text=text)

skill('balance', '制衡', 0, 7, 7, '发动时机：轮到自己出牌时。先在手牌中选中要换掉的 m 张牌，再点击“发动制衡”并确认。弃置所选牌，从牌堆获得同样数量的牌。\n发动后结束本次行动，不再普通出牌，也不额外发一张结束牌。牌堆必须足够完成换牌；未选牌即按零张处理。')
skill('anchor', '稳阵', 0, 8, 6, '被动技能，全局生效，无需点击发动。急牌轮换手牌时，你不参与交换，其余参与者继续按指定方向交换。\n急牌指定你抓两张时只获得一张；指定你禁手两回合时只禁手一回合。多次禁手仍可叠加，实际轮到你才扣除回合数。其他急牌效果正常生效。')
skill('leap', '跃阶', 0, 10, 8, '被动技能，3 至 A 的非主牌实际点数提高两级。提高时跳过主牌原点数，经过 A 后可到 2，再到主牌，最高为主牌；2 和主牌本身不提高。小王和大王均按大王使用。\n手牌保留印面，同时标出实际点数；牌型及比较使用实际点数。例如主牌为 3 时，J 视为 K，K 视为 2，A 视为主牌。')
skill('stars', '观星', 0, 9, 6, '触发时机：获得可以任意领出合法牌型的自由牌权时，包括其他人全部不出或特殊出法直接取得牌权。普通跟牌不触发。\n展示牌堆顶部相当于在场独立玩家数的牌，按你点击的顺序排列，第一张成为新的牌堆顶。必须将展示牌全部排好后确认。牌堆不足时只排列实际可取得的牌；双身的两个身份分别计数。')
skill('reflux', '回流', 0, 8, 7, '每次出牌后，可从自己刚出的实体牌中选择任意数量放到牌堆底，也可一张不选。选择完成后，这些牌不再留在弃牌区。\n本次有效出牌数达到四张时，其余在场玩家各获得“出牌数减二”张牌。例如出四张，其他人各得两张；出六张，各得四张。化双按两张计数。放回牌堆底的牌仍计入本次出牌数，批量放回时随机打乱。')
skill('clean', '净牌', 0, 8, 4, '被动技能，从开局发牌开始生效。获得印面为 3、4、5、6 的牌时，不能直接留下，系统弃置并补发等量的牌；补牌仍不符合条件时继续过滤。\n若其中某点数是本局主牌，会提示你选择要保留的主牌，其余换牌。通过发牌、赠送或买牌等方式获得牌时同样处理。无可用牌时停止补发。')
skill('money', '聚财', 0, 9, 6, '每实际打出一张有效牌获得一金钱，金钱作为资源累计，不是手牌，不影响走完判定。化双按两张计算。\n其他玩家出牌后，若你至少有四金钱，会出现购买选择。可花四金钱买入该玩家刚出的任意一张仍在弃牌区的实体牌，也可不选放弃。买走的牌进入你的手牌；桌面仍保留原完整出牌，播报说明具体取走哪张。')
skill('gift', '馈赠', 1, 7, 7, '轮到自己时，选中一张手牌，点击发动，选择另一名仍在场的玩家。将所选牌交给该玩家，然后自己从牌堆获得两张。\n发动后结束本次行动，跳过普通出牌及普通结束发牌。必须有足够牌完成获得两张的效果；对方的禁用牌过滤、绑定等获得牌效果照常处理。')
skill('stash', '藏锋', 1, 20, 12, '两个效果：①结算普通结束发牌时，若手牌少于五张，免去这次发牌；恰好五张不免。②出牌后可选择任意数量剩余手牌存入分区，也可不存。\n分区内的牌不受急牌影响，可通过分区按钮取回。它们属于尚未出过的牌：仅清空手牌不算走完，必须连同分区内未出牌全部处理完。存入分区本身不是出牌。')
skill('scavenge', '拾遗', 1, 8, 1, '前两次实际轮到自己的行动，跳过普通出牌，改为从另一名玩家最近一手中取得至少一张仍在弃牌区的实体牌。可以取多张，但必须来自同一名玩家的同一手。\n按提示选牌后确认，之后仍结算普通结束发牌。没有可取牌时直接跳过。取走的牌加入手牌，原桌面出牌保持完整显示，并播报取走的具体牌。两次之后恢复正常行动。')
skill('pressure', '施压', 1, 14, 12, '轮到自己时，选中一张实际点数为 2 的牌，点击发动并指定另一名仍在场的玩家。消耗这张牌，令目标从牌堆获得四张。\n这次技能使用不代替普通出牌，可在条件允许时继续行动。牌堆须足够完成效果，目标的过滤和绑定等效果照常处理。')
skill('suitmark', '花印', 1, 9, 9, '用包含至少两种花色的牌管上别人，并最终取得自由牌权时，给被你管上的上一出牌者添加一个花色印记。印记取你这手牌中数量最多的花色；并列时随机。单纯跟上但未获得牌权不结算。\n对方凑齐两个印记后，在下一次实际轮到自己时触发并清除：♠♠获得两张；♥♥弃两张最大牌；♣♣展示两张、至多留一张；♦♦无效果；♠♥获得两张后弃一张最大牌；♠♣先获得一张，再展示一张自选是否保留；♥♣先弃一张最大牌，再展示一张自选是否保留；♠♦获得四张；♥♦弃三张最大牌；♣♦展示三张、至多留一张。\n不保留的展示牌打乱放回牌堆底。最大牌按全局实际点数比较，同大时由本人选择。')
skill('double', '化双', 1, 7, 5, '选中一张 K、A、2 或主牌，点击“化双”，分别指定它代表的两张牌的点数和花色。两张均只能为 3、4、5，且不能选择本局主牌。\n每次出牌最多使用一张实体牌发动此效果，可与其他手牌组合；两张代表牌可以不同。牌型和出牌数量按两张计算，实际只消耗原来那张牌。指定完成后，仍需选好整手牌并点击出牌；它不是任意点数赖子。')
skill('seven', '七印', 2, 8, 8, '轮到自己时，可选中印面为 3、4、5、6 的牌，通过技能“储存”转为印记，最多存七枚。印记属于已处理的资源，不属于待出的分区手牌。\n集齐七枚后，选择“使用七印”，填写七张牌的点数及花色，组成一种合法的七张牌型并出牌，消耗全部七枚。可以组成顺子、连对之外符合张数的其他合法组合，但不能组成 4A4 系列或王炸；跟牌时仍须能管上当前牌面。')
skill('formless', '无相', 2, 8, 6, '被动改变“回”：无需匹配对方主体的花色，同一轮内不限回的次数。出牌组合仍须与对方牌型和张数相同，并符合回的其他条件。\n当前手牌少于三张时不能发动回；恰好三张允许。王没有普通花色，2 和主牌也不能作为回或被回的主体；本技能不解除这些限制。')
skill('blood', '血契', 2, 10, 5, '开局保留牌后，可另选零至五张弃置，所选数量成为初始血值。之后每次成功出牌减一血，每次不出加一血；非本人行动期间每获得一张牌再加一血，最低为零。\n结算普通结束发牌时，若手牌数大于当前血值，可选择免去本次发牌，也可照常获得一张；不大于则正常发牌。血是资源，不是未出手牌。')
skill('ascend', '升格', 2, 8, 8, '被动效果：印面为 3 至 A 的非主牌，实际点数初始提高一级。提高时跳过主牌原点数，最高到主牌；2、主牌及王自身不提高。手牌显示原点数及实际点数。\n轮到自己时，可选印面为 2 的牌发动技能，弃置后每张令提升幅度再加一级。例如初始加一，消耗一张 2 后改为加二。本局内持续有效，不能超过主牌；存成的资源不计入待出手牌。')
skill('extra', '增筹', 2, 6, 2, '在普通行动结束、应当发牌时，出现数量选择，可获得一、二或三张，由你自行决定。\n只改变这次普通结束发牌，不改变急牌或其他技能明确指定的获得张数。已经走完时不再发牌；牌堆耗尽且不轮回时只能获得实际可发的牌。')
skill('redirect', '转赠', 3, 6, 1, '普通行动结束需要发一张时，可选择照常自己获得一张，或改为指定另一名仍在场的独立玩家获得一张，自己不获得。\n目标可以是队友或对手，双身可分别指定。只替代这次普通结束发牌，不转移急牌或其他技能造成的加牌。')
skill('request', '索取', 3, 9, 3, '普通结束发牌时，可选择照常发牌，或自己不从牌堆获得牌，改为向其他每一名仍在场的独立玩家各索取两张。每名提供者自行选择交出的牌。\n对方不足两张时交出全部；若因此手牌和未出分区均清空，立即按走完结算。本技能向每人索取，不是全场合计两张；双身的两个身份独立参与。')
skill('gather', '广纳', 3, 12, 6, '从开局发牌起，不能获得 2、当前主牌及大小王；取得这些牌时弃置，并补发其他可用牌。急牌不在此禁止清单中。\n普通结束发牌时可选择获得一至五张。只改变普通发牌数量，其他效果指定的数量保持原样，但获得的牌仍受禁用点数过滤。无可用牌时停止补发。')
skill('wild', '百变', 3, 10, 10, '所有花色的 A 都拥有赖子能力，可与其他牌组成组合，逐张指定代替的非王牌点数及花色，也可以按原本 A 使用。\n选中相关 A 后点击“指定赖子”，确认声明再出牌；不能替代大小王。普通替代不能单独出，代急牌时可选择急牌效果。比较牌型和回的花色均按声明后的牌计算，桌面保留原牌与替代结果。')
skill('twins', '双身', 3, 14, 14, '开局将保留的手牌自行分为两组，每组至少一张。页面仍显示四个座位，本座位拥有两个独立身份及两个出牌区；通过“手牌 A／B”切换操作。\n两个身份相邻依次行动，各自出牌、结束发牌、记录禁手等状态；急牌和指定目标的技能可以分别选中其中一个。任一身份手牌及其未出分区清空，即本人走完，另一个身份同时停止行动。队伍及主牌升级仍按四个真实玩家计算。')
skill('pursuit', '追击', 3, 6, 3, '轮到自己时，若没有能够管上当前牌面的牌，自动连续获得牌，直到有合法响应或累计获得十张；达到上限仍不能管则不出。\n若原本已有可出的牌，提供选择，可额外获得零至十张后再决定出牌。成功出牌后免去普通结束发牌。牌堆耗尽时停止获得，不凭空补牌。')
skill('debt', '追债', 3, 9, 6, '每次管上其他玩家的牌，给被管者累计一枚追债印记，可多次叠加。\n当你获得可以任意领出的自由牌权时，其他仍在场玩家各从牌堆获得与自己追债印记数相同的牌，随后清除这些印记。普通跟牌期间不立即收债；印记是状态，不是待出的牌。')
skill('judgment', '天命', 4, 12, 12, '轮到自己且没有合法牌可以管上时，可点击发动，翻牌堆顶一张判定。若是黑桃 2 至黑桃 9，视为打出与上一手相同牌型、主体大一级的牌；显示圆圈花色，有带牌时附件统一视为 3。\n特殊出牌、王炸、4A4 系列及已到最大级的牌型不能提升。判定失败获得五张并跳过本次出牌，结束发牌按行动结算。判定牌无论成功失败均放回牌堆底，牌堆为空不能发动。')
skill('trade', '易牌', 4, 10, 2, '主动换牌：轮到自己时，选中一张王、主牌或 2 并发动，分别弃掉该牌并获得五、四或三张；不占普通出牌，牌堆须足够完成换牌。\n普通结束发牌时还可选择判定：翻牌堆顶一张后放回底部，若为黑色（黑桃或梅花），可自选额外获得零至十三张；本次普通获得一张仍照常处理。红色没有额外获得。')
skill('bond', '同契', 4, 9, 3, '每次出牌后可选择另一名玩家与自己绑定，也可放弃；关系持续至自己下次成功出牌。绑定双方能互看对方手牌。\n任意一方增加 k 张牌，另一方也从牌堆获得 k 张；任意一方减少 k 张，另一方自行选择弃置相应数量，不足则全部弃置。同步效果不递归触发自身。双方普通结束发牌可选择一至两张；任何一方清空手牌及未出分区仍正常走完。')
skill('duel', '拼点', 4, 8, 6, '获得自由牌权时，可选择发起拼点或放弃。所有在场独立玩家各自暗选一张手牌，全部选好后一起公开并弃置。\n除发起者以外，拼点牌实际大小不大于发起者的玩家，还须弃置自己最大的三张；不足三张全部弃置。最大牌同大时由本人选择；清空手牌及未出分区即走完。比较使用全局实际点数，不使用临时赖子声明。')
skill('formation', '奇阵', 4, 9, 9, '被动效果：两张 4 加一张 A 可按基础 4A4A4 出牌，具有基础特殊组合的等级；正常更大的 4A4A4 组合仍按原规则计算。\n此外，出牌前手牌严格多于十二张时，三张同点可作为三炸；十二张及以下不享受此效果，恢复四张起炸。技能不改变王炸及其他炸弹的等级顺序。')

GROUPS = {0: '标准', 1: '突破', 2: '重生', 3: '多多益善', 4: '智谋'}

def available(options):
    groups = {0} | set(options.get('skillDlc', []))
    disabled = set(options.get('disabledSkills', []))
    return [s for s in SKILLS.values() if s['group'] in groups and s['id'] not in disabled]
